using System.Collections.Immutable;
using System.Globalization;
using Aict.Core;
using Microsoft.Data.Sqlite;
namespace Aict.Storage;
public sealed class ActivityRepository {
    readonly string path;readonly object gate=new();
    public ActivityRepository(string path){if(!File.Exists(path))throw new FileNotFoundException("Initialized engine database required",path);this.path=Path.GetFullPath(path);using var c=Open();using var cmd=c.CreateCommand();cmd.CommandText="CREATE TABLE IF NOT EXISTS activity_usage(day TEXT NOT NULL,zone TEXT NOT NULL,kind TEXT NOT NULL,target TEXT NOT NULL,name TEXT NOT NULL,known_ticks INTEGER NOT NULL CHECK(known_ticks>=0),unknown_ticks INTEGER NOT NULL CHECK(unknown_ticks>=0),PRIMARY KEY(day,zone,kind,target));";cmd.ExecuteNonQuery();}
    SqliteConnection Open(){var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path,Mode=SqliteOpenMode.ReadWrite,Pooling=false,DefaultTimeout=5}.ToString());c.Open();return c;}
    public void Add(IEnumerable<ActivityFrame> frames){var rows=frames.SelectMany(frame=>ActivityAccounting.Expand(frame)).GroupBy(r=>(r.Day,r.Zone,r.Kind,r.Target)).Select(g=>g.Last() with {KnownTicks=g.Sum(r=>r.KnownTicks),UnknownTicks=g.Sum(r=>r.UnknownTicks)}).ToArray();if(rows.Length==0)return;lock(gate){using var c=Open();using var t=c.BeginTransaction();foreach(var row in rows){using var cmd=c.CreateCommand();cmd.Transaction=t;cmd.CommandText="INSERT INTO activity_usage(day,zone,kind,target,name,known_ticks,unknown_ticks) VALUES($day,$zone,$kind,$target,$name,$known,$unknown) ON CONFLICT(day,zone,kind,target) DO UPDATE SET name=excluded.name,known_ticks=known_ticks+excluded.known_ticks,unknown_ticks=unknown_ticks+excluded.unknown_ticks;";cmd.Parameters.AddWithValue("$day",row.Day);cmd.Parameters.AddWithValue("$zone",row.Zone);cmd.Parameters.AddWithValue("$kind",row.Kind);cmd.Parameters.AddWithValue("$target",row.Target);cmd.Parameters.AddWithValue("$name",row.Name);cmd.Parameters.AddWithValue("$known",row.KnownTicks);cmd.Parameters.AddWithValue("$unknown",row.UnknownTicks);cmd.ExecuteNonQuery();}using var prune=c.CreateCommand();prune.Transaction=t;prune.CommandText="DELETE FROM activity_usage WHERE day < $day;";prune.Parameters.AddWithValue("$day",rows.Select(r=>DateOnly.ParseExact(r.Day,"yyyy-MM-dd",CultureInfo.InvariantCulture)).Max().AddDays(-90).ToString("yyyy-MM-dd",CultureInfo.InvariantCulture));prune.ExecuteNonQuery();t.Commit();}}
    public ImmutableArray<ActivityCounter> ReadGaps(){lock(gate){using var c=Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT day,zone,kind,target,name,known_ticks,unknown_ticks FROM activity_usage WHERE kind='gap';";using var reader=cmd.ExecuteReader();var rows=ImmutableArray.CreateBuilder<ActivityCounter>();while(reader.Read())rows.Add(new(reader.GetString(0),reader.GetString(1),reader.GetString(2),reader.GetString(3),reader.GetString(4),reader.GetInt64(5),reader.GetInt64(6)));return rows.ToImmutable();}}
    public ImmutableArray<ActivityCounter> Read(){lock(gate){using var c=Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT day,zone,kind,target,name,known_ticks,unknown_ticks FROM activity_usage ORDER BY day DESC,known_ticks DESC LIMIT 20000;";using var reader=cmd.ExecuteReader();var result=ImmutableArray.CreateBuilder<ActivityCounter>();while(reader.Read())result.Add(new(reader.GetString(0),reader.GetString(1),reader.GetString(2),reader.GetString(3),reader.GetString(4),reader.GetInt64(5),reader.GetInt64(6)));return result.ToImmutable();}}
    public static string ToCsv(IEnumerable<ActivityCounter> rows){static string Cell(string s)=>"\""+((s.Length>0&&"=+-@\t\r".Contains(s[0]))?"'":"")+s.Replace("\"","\"\"")+"\"";var result=new System.Text.StringBuilder("day,time_zone,kind,target,name,known_seconds,unknown_seconds\r\n");foreach(var r in rows)result.AppendLine(string.Join(",",Cell(r.Day),Cell(r.Zone),Cell(r.Kind),Cell(r.Target),Cell(r.Name),(r.KnownTicks/(double)TimeSpan.TicksPerSecond).ToString("0.###",CultureInfo.InvariantCulture),(r.UnknownTicks/(double)TimeSpan.TicksPerSecond).ToString("0.###",CultureInfo.InvariantCulture)));return result.ToString();}
}
